/// <summary>
/// Handle event for RetailDiscountOffer table
/// MPJ_24248 Price Data Extract
/// </summary>
[ExtensionOf(TableStr(RetailPeriodicDiscount))]
final class METRetailPeriodicDiscountTable_Extension
{
}

Method.Source:
    /// <summary>
    /// COC update
    /// </summary>
    public void update()
    {
        boolean     statusUpdated = false;
        
        if(this.IsGUPDiscount == NoYes::Yes &&  this.Status != this.orig().Status)
        {
            statusUpdated = true;
        }

        next update();

        if(statusUpdated) 
        {
            RetailPeriodicDiscount::METProcessTrackChange(this.OfferId, SysAppCRUDOperation::Update, this.PeriodicDiscountType, this.Status);
        }
    }

    /// <summary>
    /// COC insert
    /// </summary>
    public void insert()
    {
        next insert();

        if( this.IsGUPDiscount == NoYes::Yes)
        {
            RetailPeriodicDiscount::METProcessTrackChange(this.OfferId, SysAppCRUDOperation::Create, this.PeriodicDiscountType, this.status);
        }
    }

    /// <summary>
    /// COC delete
    /// </summary>
    public void delete()
    {
        if( this.IsGUPDiscount == NoYes::Yes)
        {
            RetailPeriodicDiscount::METProcessTrackChange(this.OfferId, SysAppCRUDOperation::Delete, this.PeriodicDiscountType, RetailDisabledEnabled::Disabled);
        }

        next delete();
    }

    /// <summary>
    /// Process the change track
    /// </summary>
    /// <param name = "_OfferId">Discount id</param>
    /// <param name = "_crud">DB operation</param>
    /// <param name = "_priceChangeType">Price change type</param>
    /// <param name = "_status">Record status</param>
    public static void metProcessTrackChange(RetailOfferIdEx3 _OfferId, SysAppCRUDOperation _crud, RetailDiscountOfferTypeBase _periodicDiscountType, RetailDisabledEnabled _status)
    {
        boolean             process = false;
        METPriceChangeType  priceChangeType;

        switch(_periodicDiscountType)
        {
            case RetailDiscountOfferTypeBase::Multibuy :
            case RetailDiscountOfferTypeBase::DiscountOffer :
                if(_crud == SysAppCRUDOperation::Create && _status == RetailDisabledEnabled::Enabled)
                {
                    process = true;
                    priceChangeType = METPriceChangeType::DiscountEnabled;
                }
                else if(_crud == SysAppCRUDOperation::Update || _crud == SysAppCRUDOperation::Delete)
                {
                    process = true;
                    priceChangeType = _status == RetailDisabledEnabled::Enabled ? METPriceChangeType::DiscountEnabled : METPriceChangeType::DiscountDisabled;
                }
                break;
            case RetailDiscountOfferTypeBase::Promotion : //Margin component
                if(_crud == SysAppCRUDOperation::Create && _status == RetailDisabledEnabled::Enabled)
                {
                    process = true;
                    priceChangeType = METPriceChangeType::MarginComponentEnabled;
                }
                else if(_crud == SysAppCRUDOperation::Update  || _crud == SysAppCRUDOperation::Delete)
                {
                    process = true;
                    priceChangeType = _status == RetailDisabledEnabled::Enabled ? METPriceChangeType::MarginComponentEnabled : METPriceChangeType::MarginComponentDisabled;
                }
                break;
        }
        
        if(process)
        {
            if(_status == RetailDisabledEnabled::Enabled)
            {
                RetailPeriodicDiscount::METTrackChangeEnabled(_OfferId, _crud, priceChangeType);
            }
            else if(_status == RetailDisabledEnabled::Disabled)
            {
                RetailPeriodicDiscount::METTrackChangeDisabled(_OfferId, _crud, priceChangeType);
            }
        }
        
    }

    /// <summary>
    /// Track the change
    /// </summary>
    /// <param name = "_OfferId">Discount id</param>
    /// <param name = "_crud">DB operation</param>
    /// <param name = "_priceChangeType">Price change type</param>
    public static void metTrackChangeEnabled(RetailOfferIdEx3 _OfferId, SysAppCRUDOperation _crud, METPriceChangeType _priceChangeType)
    {
        //Find base table and add to container of variables. Unpacking Inheritance based table to Common gives null values
        RetailPeriodicDiscount  retailPeriodicDiscountLoc;

        retailPeriodicDiscountLoc = RetailPeriodicDiscount::findByOfferId(_OfferId);

        Global::runAsync(classNum(METPriceChangeEventManage),
                        staticMethodStr(METPriceChangeEventManage, processEvent),
                        [_priceChangeType, retailPeriodicDiscountLoc, _crud],
                        System.Threading.CancellationToken::None,
                        classNum(METPriceChangeEventManage),
                        staticMethodStr(METPriceChangeEventManage, callBackResult));
        
    }

    /// <summary>
    /// Track the change. Run in real time instead of seperate thread. Force user to wait while we capture existing state before changes are made
    /// </summary>
    /// <param name = "_OfferId">Discount id</param>
    /// <param name = "_crud">DB operation</param>
    /// <param name = "_priceChangeType">Price change type</param>
    public static void metTrackChangeDisabled(RetailOfferIdEx3 _OfferId, SysAppCRUDOperation _crud, METPriceChangeType _priceChangeType)
    {
        //Find base table and add to container of variables. Unpacking Inheritance based table to Common gives null values
        RetailPeriodicDiscount  retailPeriodicDiscountLoc;
        container   resultCon;

        retailPeriodicDiscountLoc = RetailPeriodicDiscount::findByOfferId(_OfferId);

        resultCon = SysOperationSandbox::callStaticMethod(classNum(METPriceChangeEventManage),staticMethodStr(METPriceChangeEventManage,processEvent),
            [_priceChangeType, retailPeriodicDiscountLoc, _crud], "@MET:WaitingPriceChangeTrackingProcess");

        METPriceChangeEventManage::buildResultMessage(resultCon);
    }
